import{_ as t,C as s,o as n,c as i,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Digital Employee Daily 003 — Computer Use Requires an Observable Action–State Loop","description":"","frontmatter":{"title":"Digital Employee Daily 003 — Computer Use Requires an Observable Action–State Loop","date":"2026-08-02","column":"digital-employee","category":"daily","summary":"OpenAI and Anthropic computer-use guidance shows that reliable GUI work depends on an external harness that observes state, executes bounded actions, captures evidence, and verifies the resulting state.","sources":["OpenAI Computer use guide","Anthropic Computer use tool documentation"],"outline":"deep"},"headers":[],"relativePath":"en/digital-employee/2026-08-02-computer-use-action-state-loop.md","filePath":"en/digital-employee/2026-08-02-computer-use-action-state-loop.md","lastUpdated":1787410041000}'),l={name:"en/digital-employee/2026-08-02-computer-use-action-state-loop.md"};function p(c,e,d,h,u,m){const a=s("ArticleCover");return n(),i("div",null,[o(a,{image:"/assets/covers/computer-use-action-state-loop-cover-v2.jpg",kicker:"Digital Employee · Daily 003",title:"Computer Use Requires an Observable Action–State Loop",summary:"A model does not complete GUI work by intention alone; a governed harness must observe, act, capture, approve, and verify.",version:"DD003",status:"Production Test V1 · 2026-08-02",languageHref:"/zh/digital-employee/2026-08-02-computer-use-action-state-loop",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Computer use is often described as an Agent “operating a browser” or “using a desktop.” The official implementation guidance from OpenAI and Anthropic describes a more precise system.</p><p>The model interprets a visual state and proposes an action. An application-controlled harness executes that action in a browser, virtual machine, or desktop environment, captures the next state, and sends it back to the model. This repeats until the work reaches a completion condition or a policy gate requires human authority.</p><p>The Research Center judgment is:</p><blockquote><p>A computer-using Digital Employee is not a model with mouse access. It is an observable action–state loop governed by an external runtime, explicit authority, evidence capture, and final-state verification.</p></blockquote><p>This distinction matters because organizational work is completed by a change in business state, not by the model saying that it clicked the right button.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="selected-primary-material" tabindex="-1">Selected primary material <a class="header-anchor" href="#selected-primary-material" aria-label="Permalink to &quot;Selected primary material&quot;">​</a></h3><ol><li><strong>OpenAI Computer use guide</strong> — selected because it defines the common harness shapes, screenshot/action cycle, isolated execution environment, treatment of page content as untrusted input, and human approval for high-impact actions.</li><li><strong>Anthropic Computer use tool documentation</strong> — selected because it separates the model-facing tool from the developer-provided environment and agent loop, and documents isolation, minimal privilege, allowlisting, prompt-injection risk, and confirmation for consequential actions.</li></ol><p>Both are provider documents. They explain supported mechanisms and recommended safeguards. They are not independent evidence that every GUI task is reliable, safe, or economically suitable for unattended production.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-the-model-proposes-the-harness-executes" tabindex="-1">1. The model proposes; the harness executes <a class="header-anchor" href="#_1-the-model-proposes-the-harness-executes" aria-label="Permalink to &quot;1. The model proposes; the harness executes&quot;">​</a></h3><p>In both implementations, the model does not directly control an operating system. It returns structured actions such as click, type, scroll, key press, or screenshot request. Developer-controlled code interprets those actions and applies them to an environment.</p><p>This creates a clear technical boundary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model reasoning</span></span>
<span class="line"><span>    ↓ proposed action</span></span>
<span class="line"><span>Execution harness</span></span>
<span class="line"><span>    ↓ controlled operation</span></span>
<span class="line"><span>Browser / desktop / application</span></span>
<span class="line"><span>    ↓ resulting state</span></span>
<span class="line"><span>Screenshot or structured observation</span></span>
<span class="line"><span>    ↺ back to model</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis from the OpenAI and Anthropic computer-use documentation.</em></p><p>The runtime therefore owns execution semantics, environment isolation, credentials, network reachability, timeouts, and evidence capture.</p><h3 id="_2-every-action-depends-on-a-fresh-state" tabindex="-1">2. Every action depends on a fresh state <a class="header-anchor" href="#_2-every-action-depends-on-a-fresh-state" aria-label="Permalink to &quot;2. Every action depends on a fresh state&quot;">​</a></h3><p>The normal loop is not “generate a long script and hope it works.” The system repeatedly captures the current interface, asks for the next action, executes it, and returns an updated screenshot or observation.</p><p>This is necessary because interfaces are stateful and non-deterministic. A click may open a dialog, trigger validation, fail silently, change navigation, or expose a new security boundary. The next action should be based on the observed result rather than the intended result.</p><h3 id="_3-security-belongs-in-the-runtime-boundary" tabindex="-1">3. Security belongs in the runtime boundary <a class="header-anchor" href="#_3-security-belongs-in-the-runtime-boundary" aria-label="Permalink to &quot;3. Security belongs in the runtime boundary&quot;">​</a></h3><p>The two providers converge on similar safeguards:</p><ul><li>use an isolated browser, container, or virtual machine;</li><li>minimize inherited environment variables and host access;</li><li>constrain sites, accounts, tools, and actions;</li><li>treat interface content as potentially untrusted;</li><li>keep humans in the loop for purchases, authentication, destructive changes, or other hard-to-reverse actions;</li><li>avoid giving the model unrestricted access to sensitive data or credentials.</li></ul><p>These are not prompt-writing concerns alone. They require enforceable runtime controls.</p><h3 id="_4-completion-cannot-be-inferred-from-the-last-click" tabindex="-1">4. Completion cannot be inferred from the last click <a class="header-anchor" href="#_4-completion-cannot-be-inferred-from-the-last-click" aria-label="Permalink to &quot;4. Completion cannot be inferred from the last click&quot;">​</a></h3><p>A click is an attempted operation, not proof of a completed business outcome. The system must inspect the resulting state: confirmation number, updated record, changed status, generated file, successful search result, or another application-specific condition.</p><p>A Digital Employee runtime therefore needs a verifier that is independent of the model’s narrative.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="the-minimum-computer-operation-record" tabindex="-1">The minimum computer-operation record <a class="header-anchor" href="#the-minimum-computer-operation-record" aria-label="Permalink to &quot;The minimum computer-operation record&quot;">​</a></h3><p>Each GUI operation should produce a durable record:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">computer_operation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  step_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  actor_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pre_state_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  proposed_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  policy_decision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  human_approval_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  execution_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  post_state_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  validator_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  next_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>This does not require storing every screenshot forever. Retention can follow risk and privacy policy. What matters is that the system can prove which state was observed, which action was authorized, what actually happened, and why the workflow advanced.</p><h3 id="action-state-and-evidence-are-different-facts" tabindex="-1">Action, state, and evidence are different facts <a class="header-anchor" href="#action-state-and-evidence-are-different-facts" aria-label="Permalink to &quot;Action, state, and evidence are different facts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Runtime fact</th><th>Question answered</th><th>Typical evidence</th></tr></thead><tbody><tr><td>Proposed action</td><td>What did the model request?</td><td>Structured tool call</td></tr><tr><td>Authorized action</td><td>Was the request allowed?</td><td>Policy and approval event</td></tr><tr><td>Executed action</td><td>What did the harness attempt?</td><td>Runtime event and return code</td></tr><tr><td>Resulting state</td><td>What did the application become?</td><td>Screenshot, DOM fact, API readback, file hash</td></tr><tr><td>Completion judgment</td><td>Did the WorkOrder outcome hold?</td><td>Task-specific validator</td></tr></tbody></table><p><em>Table: joinwell52 Research Center synthesis.</em></p><p>Conflating these facts creates false success. A tool call may be valid but not executed; execution may succeed technically but produce the wrong state; the desired state may appear temporarily but fail persistence or later validation.</p><h3 id="a-digital-employee-is-not-a-scraper" tabindex="-1">A Digital Employee is not a scraper <a class="header-anchor" href="#a-digital-employee-is-not-a-scraper" aria-label="Permalink to &quot;A Digital Employee is not a scraper&quot;">​</a></h3><p>A scraper extracts data from a predetermined page structure. A Digital Employee performs a governed sequence of operations inside an organizational role: open an application, authenticate through an approved path, locate a record, enter or review data, respond to interface state, escalate exceptions, and prove completion.</p><p>Programmatic APIs remain preferable when they are stable, authorized, and sufficient. Computer use is valuable where work is only available through human-facing software or where visual context matters. The runtime should choose the lowest-risk suitable channel rather than treating GUI control as a universal replacement for APIs.</p><h3 id="human-authority-is-a-workflow-node" tabindex="-1">Human authority is a workflow node <a class="header-anchor" href="#human-authority-is-a-workflow-node" aria-label="Permalink to &quot;Human authority is a workflow node&quot;">​</a></h3><p>Approval should not be an informal interruption. The workflow should enter an explicit state such as <code>waiting_human_authority</code>, preserve the proposed action and visible context, identify the approving role, and resume only with a durable decision.</p><p>This turns “human in the loop” from a product slogan into an auditable state transition.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This note does not edit a TMPA publication. It provides research evidence for explicit Event, Authority, Lifecycle, Evidence, and Integrity references around external actions. A deterministic reconstruction should distinguish proposed action, permitted action, execution event, observed state, and completion judgment.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>Computer Operation should become a first-class Work Runtime node with:</p><ol><li>a bounded application and account context;</li><li>pre-action state capture;</li><li>structured action proposal;</li><li>enforceable policy and approval gates;</li><li>post-action state capture;</li><li>task-specific completion validation;</li><li>exception, retry, and escalation states;</li><li>privacy-aware evidence retention.</li></ol><p>The Position definition should state which applications and action classes the Digital Employee may use without approval.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu should treat computer use as a governed runtime adapter, not as unrestricted browser automation. A safe implementation path is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WorkOrder</span></span>
<span class="line"><span>→ Operation node</span></span>
<span class="line"><span>→ Computer-use adapter</span></span>
<span class="line"><span>→ isolated browser/desktop</span></span>
<span class="line"><span>→ evidence event</span></span>
<span class="line"><span>→ validator</span></span>
<span class="line"><span>→ QA or human gate</span></span>
<span class="line"><span>→ completion</span></span></code></pre></div><p>The first validation case should use a controlled local application with known initial states and executable validators. The runtime should log every state transition and prove that a resumed session does not duplicate a consequential action.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>Define the Computer Operation contract and allowed action taxonomy.</li><li>Build a controlled local benchmark with login, search, form entry, confirmation, error, and recovery cases.</li><li>Compare screenshot-only evidence with DOM, API readback, and business-record validation.</li><li>Define which actions require Position-level pre-authorization and which require per-run human approval.</li><li>Test checkpoint and resume behavior after browser, network, and model failures.</li><li>Measure task success by final state, not by the number of completed clicks.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenAI, <strong>Computer use</strong>: <a href="https://developers.openai.com/api/docs/guides/tools-computer-use" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/tools-computer-use</a></li><li>Anthropic, <strong>Computer use tool</strong>: <a href="https://platform.claude.com/docs/en/agents-and-tools/tool-use/computer-use-tool" target="_blank" rel="noreferrer">https://platform.claude.com/docs/en/agents-and-tools/tool-use/computer-use-tool</a></li></ol>`,57))])}const b=t(l,[["render",p]]);export{g as __pageData,b as default};
